//! Rust port of /workspace/dataset/test7.cpp (RGB blend + default formatting).
//!
//! Mirrors the C++ behavior:
//! - defaults: r1=0.3 g1=0.4 b1=0.5 r2=0.7 g2=0.2 b2=0.1 ratio=0.3 (f32);
//! - argc > 5 (>= 5 user args): r1..g2 = stof(argv[1..=5]); b2 is never
//!   read from the command line;
//! - argc > 6: ratio = stof(argv[6]); further args are ignored;
//! - blend per channel in f32: out = c1*(1.0-ratio) + c2*ratio;
//! - output: "<r> <g> <b>\n" with C++ `std::cout << float` formatting;
//! - a failed stof aborts like an uncaught C++ exception: two stderr lines
//!   and exit code 134 (SIGABRT).

#[path = "src/fmt.rs"]
mod fmt;
#[path = "src/parse.rs"]
mod parse;

use parse::StofError;

/// Parses like std::stof; on failure replicates the uncaught-exception abort
/// of the reference program (message on stderr, exit code 134).
fn stof_or_abort(s: &str) -> f32 {
    match parse::stof(s) {
        Ok(v) => v,
        Err(kind) => {
            let name = match kind {
                StofError::InvalidArgument => "std::invalid_argument",
                StofError::OutOfRange => "std::out_of_range",
            };
            eprintln!("terminate called after throwing an instance of '{}'", name);
            eprintln!("  what():  stof");
            std::process::exit(134);
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut r1: f32 = 0.3;
    let mut g1: f32 = 0.4;
    let mut b1: f32 = 0.5;
    let mut r2: f32 = 0.7;
    let mut g2: f32 = 0.2;
    let b2: f32 = 0.1; // never read from the command line
    let mut ratio: f32 = 0.3;

    // args[0] is the program name, so args.len() mirrors C++ argc.
    if args.len() > 5 {
        r1 = stof_or_abort(&args[1]);
        g1 = stof_or_abort(&args[2]);
        b1 = stof_or_abort(&args[3]);
        r2 = stof_or_abort(&args[4]);
        g2 = stof_or_abort(&args[5]);
    }
    if args.len() > 6 {
        ratio = stof_or_abort(&args[6]);
    }

    // f32 throughout, matching the C++ float arithmetic.
    let one_minus = 1.0f32 - ratio;
    let r = r1 * one_minus + r2 * ratio;
    let g = g1 * one_minus + g2 * ratio;
    let b = b1 * one_minus + b2 * ratio;

    println!(
        "{} {} {}",
        fmt::format_f32(r),
        fmt::format_f32(g),
        fmt::format_f32(b)
    );
}

// Generates random arg sets for differential fuzzing.
// Line format: fields separated by \x1f; first field is the arg count.
use std::fmt::Write as _;

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    fn below(&mut self, n: u64) -> u64 { self.next() % n }
    fn range(&mut self, lo: i64, hi: i64) -> i64 { lo + (self.next() % ((hi - lo) as u64)) as i64 }
}

fn rand_val(r: &mut Rng, lo: i64, hi: i64) -> String {
    // random value in [lo, hi] with 0..9 decimal places
    let scale = [1i64, 10, 100, 1000, 10000, 100000, 1000000, 10000000, 100000000, 1000000000];
    let s = scale[r.below(10) as usize];
    let n = r.range(lo * s, hi * s);
    if s == 1 {
        return format!("{}", n);
    }
    let neg = n < 0;
    let a = n.unsigned_abs();
    let int = a / s as u64;
    let frac = a % s as u64;
    let digits = s.ilog10();
    let mut out = String::new();
    if neg { out.push('-'); }
    write!(out, "{}.{:0width$}", int, frac, width = digits as usize).unwrap();
    // sometimes trim trailing zeros, sometimes use exponent form
    match r.below(6) {
        0 => {
            while out.ends_with('0') { out.pop(); }
            if out.ends_with('.') { out.pop(); }
            out
        }
        1 => out,
        _ => out,
    }
}

fn special(r: &mut Rng) -> String {
    const SP: &[&str] = &[
        "1e30", "-1e30", "3.4e38", "3.5e38", "1e39", "1e-30", "1e-38", "1.17549435e-38",
        "1e-45", "1e-46", "1e400", "-1e400", "1e-400", "abc", "", "  1.5", "1.5xyz",
        "nan", "-nan", "nan(1)", "inf", "-inf", "infinity", "-0", ".5", "5.", "1e", "1e+",
        "0x10", "0x1.8p3", "0x1p-149", "0x1p128", "0x", "+3", "007", "1,5", "2e-1",
        "123456.789", "9.999999e5", "0.000123456", "16777217", "e5", ".", "+", "0x1.fffffep127",
        "3.4028236e38", "1e-3e2", "  -2.75e1xyz", "0X1P4", "1E5", "0.1e-44",
    ];
    SP[r.below(SP.len() as u64) as usize].to_string()
}

fn main() {
    let n: usize = std::env::args().nth(1).and_then(|s| s.parse().ok()).unwrap_or(2500);
    let mut r = Rng(0xdeadbeef1234567);
    let mut out = String::new();
    for _ in 0..n {
        let argc = r.below(9); // 0..8 user args
        let mut fields: Vec<String> = Vec::new();
        for i in 0..argc {
            let v = match r.below(10) {
                0 | 1 => special(&mut r),
                _ => {
                    if i == 5 {
                        rand_val(&mut r, -1, 2) // ratio range
                    } else {
                        rand_val(&mut r, -3, 3)
                    }
                }
            };
            fields.push(v);
        }
        let mut line = format!("{}", argc);
        for f in fields {
            line.push('\x1f');
            line.push_str(&f);
        }
        out.push_str(&line);
        out.push('\n');
    }
    print!("{}", out);
}

