/// Emulates the NaN behavior of one x86-64 SSE scalar op `dst OP src`
/// whose IEEE result is `r`: when `r` is NaN, a NaN operand is propagated
/// (quieted; dst wins if both are NaN), and if no operand is NaN the op was
/// invalid (0*inf, inf-inf) and yields the QNaN indefinite 0xFFC00000.
/// For non-NaN `r` the plain IEEE result is returned unchanged.
fn sse(dst: f32, src: f32, r: f32) -> f32 {
    if r.is_nan() {
        if dst.is_nan() {
            return f32::from_bits(dst.to_bits() | 0x0040_0000);
        }
        if src.is_nan() {
            return f32::from_bits(src.to_bits() | 0x0040_0000);
        }
        return f32::from_bits(0xffc0_0000);
    }
    r
}

/// One blend channel, following the reference binary's exact instruction
/// schedule (see ColorConverter::blend disassembly):
///   s  = subss(1.0, ratio)        // dst = 1.0 const
///   t1 = mulss(c1, s)             // dst = c1
///   t2 = mulss(c2, ratio)         // dst = c2
///   g/b: addss(t1, t2)  (dst = t1);  r: addss(t2, t1)  (dst = t2)
/// The schedule only matters for NaN results (sign/payload propagation).
fn blend_channel(c1: f32, c2: f32, ratio: f32, r_order: bool) -> f32 {
    let s = sse(1.0, ratio, 1.0 - ratio);
    let t1 = sse(c1, s, c1 * s);
    let t2 = sse(c2, ratio, c2 * ratio);
    if r_order {
        sse(t2, t1, t2 + t1)
    } else {
        sse(t1, t2, t1 + t2)
    }
}

